"use client"

import { useMemo, useState, type ReactNode } from "react"
import { Activity, ArrowDownLeft, ArrowUpRight, Bell, Boxes, ChartNoAxesCombined, ChevronDown, ChevronRight, CircleHelp, LayoutDashboard, Menu, PackageSearch, Plus, Printer, Search, ShoppingCart, SlidersHorizontal, Truck, X, Download, Check } from "lucide-react"
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts"
import { InventoryProvider, formatINR, godowns, useInventory, type Godown, type InventoryItem, type LineInput, type PurchaseOrder, type SaleOrder } from "@/lib/inventory-store"
import { Toaster, toast } from "sonner"

type View = "Dashboard" | "Sales" | "Purchase" | "Stock" | "Reports"
type Status = "All" | "In stock" | "Low stock" | "Out of stock"
const navItems: { label: View; icon: typeof LayoutDashboard }[] = [{ label: "Dashboard", icon: LayoutDashboard }, { label: "Sales", icon: ShoppingCart }, { label: "Purchase", icon: Truck }, { label: "Stock", icon: Boxes }, { label: "Reports", icon: ChartNoAxesCombined }]
const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
const dateLabel = (date: string) => { const [year, month, day] = date.split("-").map(Number); return `${day} ${monthNames[month - 1]} ${year}` }
const timeLabel = (date: string) => { const indiaTime = new Date(new Date(date).getTime() + 330 * 60_000); const hours = indiaTime.getUTCHours(); return `${indiaTime.getUTCDate()} ${monthNames[indiaTime.getUTCMonth()]}, ${hours % 12 || 12}:${String(indiaTime.getUTCMinutes()).padStart(2, "0")} ${hours >= 12 ? "pm" : "am"}` }
const itemStatus = (item: InventoryItem): Status => item.quantity === 0 ? "Out of stock" : item.quantity <= item.minLevel ? "Low stock" : "In stock"
const statusClass = (status: string) => status === "Paid" || status === "Received" || status === "In stock" ? "bg-emerald-50 text-emerald-800" : status === "Draft" || status === "Pending" || status === "Low stock" ? "bg-amber-50 text-amber-800" : status === "Out of stock" ? "bg-rose-50 text-rose-800" : "bg-slate-100 text-slate-700"
const buttonClass = "inline-flex min-h-9 items-center justify-center gap-2 rounded-lg border border-[#e4e4e7] bg-white px-3 text-sm font-medium text-slate-700 transition-colors duration-200 hover:bg-slate-50"
const primaryClass = "inline-flex min-h-9 items-center justify-center gap-2 rounded-lg bg-[#09090b] px-3 text-sm font-medium text-white transition-colors duration-200 hover:bg-[#27272a] disabled:cursor-not-allowed disabled:opacity-50"

function AppContent() {
  const inventory = useInventory()
  const { items, sales, purchases, movements, resetDemoData } = inventory
  const [view, setView] = useState<View>("Dashboard")
  const [search, setSearch] = useState("")
  const [mobileNav, setMobileNav] = useState(false)
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [profileOpen, setProfileOpen] = useState(false)
  const [periodDays, setPeriodDays] = useState(30)
  const [drawer, setDrawer] = useState<{ type: "stock"; id: string } | { type: "purchase"; id: string } | { type: "sale"; id: string } | null>(null)
  const [modal, setModal] = useState<"sale" | "purchase" | null>(null)
  const [prefillItem, setPrefillItem] = useState<string | undefined>()
  const lowStock = items.filter((item) => item.quantity <= item.minLevel)
  const stockValue = items.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0)
  const cutoff = new Date(`${new Date(Date.now() + 330 * 60_000).toISOString().slice(0, 10)}T00:00:00Z`)
  cutoff.setUTCDate(cutoff.getUTCDate() - periodDays + 1)
  const periodSales = sales.filter((sale) => sale.date >= cutoff.toISOString().slice(0, 10))
  const periodSalesTotal = periodSales.reduce((sum, sale) => sum + sale.totalAmount, 0)
  const pendingPOs = purchases.filter((order) => order.status === "Pending").length
  const openPurchase = (itemId?: string) => { setPrefillItem(itemId); setModal("purchase") }
  const filteredLow = lowStock.filter((item) => `${item.sku} ${item.name} ${item.godown}`.toLowerCase().includes(search.toLowerCase()))
  const showStockSearch = (value: string) => { setSearch(value); setView("Stock") }
  const openStockItem = (id: string) => { setView("Stock"); setSearch(""); setMobileNav(false); setNotificationsOpen(false); setDrawer({ type: "stock", id }) }

  return <div className="min-h-screen bg-[#fafafa] text-slate-900">
    <Toaster position="top-right" richColors closeButton />
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[240px] flex-col border-r border-[#e4e4e7] bg-white transition-transform duration-200 ease-out md:translate-x-0 ${mobileNav ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex h-[72px] items-center justify-between border-b border-[#e4e4e7] px-6"><button className="flex items-center gap-3" onClick={() => setView("Dashboard")} aria-label="Gada Electronics home"><span className="flex size-9 items-center justify-center rounded-xl bg-[#09090b] text-white"><Boxes size={19}/></span><span className="min-w-0 text-left"><span className="block text-[16px] font-semibold tracking-[-0.04em]">Gada Electronics</span><span className="block text-[11px] leading-4 text-slate-500">Goregaon East · Mumbai</span></span></button><button className="rounded-md p-2 text-slate-500 md:hidden" onClick={() => setMobileNav(false)} aria-label="Close navigation"><X size={18}/></button></div>
      <div className="px-4 pt-7"><p className="mb-3 px-3 text-xs font-semibold text-slate-500">Workspace</p><nav aria-label="Main navigation" className="flex flex-col gap-1">{navItems.map(({ label, icon: Icon }) => <button key={label} onClick={() => { setView(label); setMobileNav(false); setSearch("") }} className={`flex h-10 items-center gap-3 rounded-lg px-3 text-sm font-medium transition-colors duration-200 ${view === label ? "bg-slate-100 text-slate-950" : "text-slate-600 hover:bg-slate-50 hover:text-slate-900"}`}><Icon size={17} strokeWidth={1.8}/><span>{label}</span>{label === "Stock" && lowStock.length > 0 && <span className="ml-auto rounded-full bg-amber-50 px-2 py-0.5 text-xs font-semibold text-amber-800">{lowStock.length}</span>}</button>)}</nav></div>
      <div className="relative mt-auto border-t border-[#e4e4e7] p-4"><button aria-expanded={profileOpen} aria-haspopup="menu" onClick={() => setProfileOpen((open) => !open)} className="mb-2 flex w-full items-center gap-3 rounded-lg bg-slate-50 p-3 text-left"><span className="flex size-9 items-center justify-center rounded-full bg-slate-200 text-xs font-semibold text-slate-700">JG</span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">Jethalal Gada</span><span className="block truncate text-xs text-slate-500">Owner · Goregaon East</span></span><ChevronDown size={15} className="text-slate-500"/></button>{profileOpen && <div role="menu" className="mb-2 rounded-lg border border-[#e4e4e7] bg-white p-1 shadow-lg"><button role="menuitem" onClick={() => { setProfileOpen(false); if (window.confirm("Restore all sample inventory, orders, and activity?")) resetDemoData() }} className="w-full rounded-md px-3 py-2 text-left text-sm text-slate-600 hover:bg-slate-50">Reset demo data</button></div>}</div>
    </aside>
    {mobileNav && <button aria-label="Dismiss navigation" className="fixed inset-0 z-30 bg-slate-900/20 md:hidden" onClick={() => setMobileNav(false)}/>}
    <div className="md:pl-[240px]">
      <header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-[#e4e4e7] bg-white/95 px-5 backdrop-blur md:px-8"><div className="flex items-center gap-3"><button className="rounded-lg p-2 text-slate-600 hover:bg-slate-100 md:hidden" aria-label="Open navigation" onClick={() => setMobileNav(true)}><Menu size={19}/></button><h1 className="text-lg font-semibold tracking-[-0.025em]">{view}</h1><ChevronRight className="hidden text-slate-400 sm:block" size={15}/><span className="hidden text-sm text-slate-500 sm:block">{view === "Dashboard" ? "Inventory overview" : "Gada Electronics workspace"}</span></div><div className="flex items-center gap-2 sm:gap-3"><label className="relative hidden sm:block"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={search} onChange={(event) => showStockSearch(event.target.value)} placeholder="Search inventory..." aria-label="Search inventory" className="h-9 w-[200px] rounded-lg border border-[#e4e4e7] bg-white pl-9 pr-3 text-sm outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-900/10 lg:w-[250px]"/></label><div className="relative"><button aria-label="Notifications" aria-expanded={notificationsOpen} onClick={() => setNotificationsOpen((open) => !open)} className="relative rounded-lg p-2 text-slate-500 hover:bg-slate-100"><Bell size={18}/>{lowStock.length > 0 && <span className="absolute right-1 top-1 size-2 rounded-full bg-rose-600"/>}</button>{notificationsOpen && <section aria-label="Low stock notifications" className="absolute right-0 top-12 z-50 w-[min(340px,calc(100vw-2rem))] rounded-xl border border-[#e4e4e7] bg-white p-4 shadow-xl"><div className="flex items-center justify-between"><h2 className="text-sm font-semibold">Low stock alerts</h2><span className="rounded-full bg-amber-50 px-2 py-0.5 text-xs font-semibold text-amber-800">{lowStock.length}</span></div>{lowStock.length ? <ul className="mt-2 max-h-72 divide-y divide-slate-100 overflow-y-auto">{lowStock.map((item) => <li key={item.id}><button onClick={() => openStockItem(item.id)} className="w-full py-2 text-left"><span className="block truncate text-sm font-medium">{item.name}</span><span className="text-xs text-slate-500">{item.quantity} {item.unit} · minimum {item.minLevel}</span></button></li>)}</ul> : <p className="mt-3 text-sm text-slate-500">No items need attention.</p>}</section>}</div><button className={`${buttonClass} !hidden sm:!inline-flex`} onClick={() => openPurchase()}><Plus size={16}/>New purchase</button><button className={primaryClass} onClick={() => setModal("sale")}><Plus size={16}/>New sale</button></div></header>
      <main className="mx-auto max-w-[1600px] px-5 py-7 md:px-8">{view === "Dashboard" ? <Dashboard items={items} lowStock={filteredLow} stockValue={stockValue} periodSales={periodSalesTotal} periodDays={periodDays} onPeriodChange={setPeriodDays} pendingPOs={pendingPOs} movements={movements} onNavigate={setView} onSelect={(id) => setDrawer({ type: "stock", id })} onReorder={openPurchase} onClearSearch={() => setSearch("")}/> : view === "Stock" ? <StockView items={items} movements={movements} search={search} onSearch={setSearch} onSelect={(id) => setDrawer({ type: "stock", id })}/> : view === "Purchase" ? <PurchaseView purchases={purchases} onSelect={(id) => setDrawer({ type: "purchase", id })} onCreate={() => openPurchase()} onReceive={inventory.markPurchaseReceived}/> : view === "Sales" ? <SalesView sales={sales} onSelect={(id) => setDrawer({ type: "sale", id })} onCreate={() => setModal("sale")} onPaid={inventory.markSalePaid}/> : <ReportsView items={items} sales={sales} purchases={purchases}/> }</main>
    </div>
    {drawer && <DetailDrawer drawer={drawer} onClose={() => setDrawer(null)} onReceive={inventory.markPurchaseReceived} onAdjust={inventory.adjustStock} onPaid={inventory.markSalePaid}/>}
    {modal && <OrderModal type={modal} prefillItem={prefillItem} onClose={() => setModal(null)} onSale={inventory.createSale} onPurchase={inventory.createPurchaseOrder}/>}
  </div>
}

function Dashboard({ items, lowStock, stockValue, periodSales, periodDays, onPeriodChange, pendingPOs, movements, onNavigate, onSelect, onReorder, onClearSearch }: { items: InventoryItem[]; lowStock: InventoryItem[]; stockValue: number; periodSales: number; periodDays: number; onPeriodChange: (days: number) => void; pendingPOs: number; movements: ReturnType<typeof useInventory>["movements"]; onNavigate: (view: View) => void; onSelect: (id: string) => void; onReorder: (id?: string) => void; onClearSearch: () => void }) {
  return <><div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="text-sm text-slate-600">{new Intl.DateTimeFormat("en-IN", { weekday: "long", day: "numeric", month: "long", year: "numeric", timeZone: "Asia/Kolkata" }).format(new Date())}</p><h2 className="mt-1 text-[26px] font-semibold tracking-[-0.04em]">Good morning, Jethalal</h2><p className="mt-1 text-sm text-slate-600">Here&apos;s what&apos;s happening across your inventory today.</p></div><label className={`${buttonClass} cursor-pointer`}><SlidersHorizontal size={15}/><span className="sr-only">Sales date range</span><select aria-label="Sales date range" value={periodDays} onChange={(event) => onPeriodChange(Number(event.target.value))} className="cursor-pointer appearance-none bg-transparent outline-none"><option value={7}>Last 7 days</option><option value={30}>Last 30 days</option><option value={90}>Last 90 days</option></select><ChevronDown size={14}/></label></div><div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{ title: "Total stock value", value: formatINR(stockValue), note: "Across 3 locations", icon: Boxes, trend: "+8.2%", color: "emerald" }, { title: "Low stock alerts", value: `${lowStock.length} items`, note: "Require your attention", icon: Activity, trend: "Needs attention", color: "amber" }, { title: `Sales in last ${periodDays} days`, value: formatINR(periodSales), note: "Confirmed and paid orders", icon: ShoppingCart, trend: "Live total", color: "emerald" }, { title: "Pending purchase orders", value: `${pendingPOs} orders`, note: "Expected this week", icon: Truck, trend: "On track", color: "slate" }].map(({ title, value, note, icon: Icon, trend, color }) => <article key={title} className="rounded-xl border border-[#e4e4e7] bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,0.03)]"><div className="flex items-center justify-between"><span className="text-sm font-medium text-slate-600">{title}</span><span className="flex size-9 items-center justify-center rounded-lg bg-slate-50 text-slate-600"><Icon size={17}/></span></div><p className="mt-4 text-[25px] font-semibold tracking-[-0.04em] tabular-nums">{value}</p><div className="mt-2 flex items-center justify-between gap-2"><span className="text-xs text-slate-500">{note}</span><span className={`rounded-full px-2 py-1 text-[11px] font-medium ${color === "emerald" ? "bg-emerald-50 text-emerald-800" : color === "amber" ? "bg-amber-50 text-amber-800" : "bg-slate-100 text-slate-700"}`}>{trend}</span></div></article>)}</div><div className="mt-6 grid grid-cols-1 gap-5 xl:grid-cols-[minmax(0,1.55fr)_minmax(340px,1fr)]"><section className="overflow-hidden rounded-xl border border-[#e4e4e7] bg-white"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e4e4e7] px-5 py-4"><div><h3 className="text-base font-semibold">Low stock alerts</h3><p className="mt-1 text-sm text-slate-500">Items at or below their minimum stock level</p></div><button onClick={() => onNavigate("Stock")} className="text-sm font-medium text-emerald-700">View all stock <ChevronRight className="ml-1 inline" size={15}/></button></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left"><thead className="bg-slate-50/80"><tr className="text-xs font-medium text-slate-500"><th className="px-5 py-3">SKU</th><th className="px-4 py-3">Item name</th><th className="px-4 py-3">Godown</th><th className="px-4 py-3">Current vs min</th><th className="px-4 py-3">Status</th><th className="px-5 py-3 text-right">Action</th></tr></thead><tbody className="divide-y divide-[#e4e4e7]">{lowStock.map((item) => <tr key={item.id} onClick={() => onSelect(item.id)} className="cursor-pointer hover:bg-slate-50/70"><td className="whitespace-nowrap px-5 py-4 font-mono text-xs font-medium text-slate-600">{item.sku}</td><td className="px-4 py-4"><p className="max-w-[190px] truncate text-sm font-medium">{item.name}</p><p className="mt-1 text-xs text-slate-500">{item.category}</p></td><td className="whitespace-nowrap px-4 py-4 text-sm text-slate-600">{item.godown}</td><td className="px-4 py-4"><StockLevel item={item}/></td><td className="px-4 py-4"><StatusBadge status={itemStatus(item)}/></td><td className="px-5 py-4 text-right"><button onClick={(event) => { event.stopPropagation(); onReorder(item.id) }} className="h-8 rounded-md border border-[#e4e4e7] bg-white px-3 text-xs font-semibold text-slate-700 hover:border-emerald-300 hover:bg-emerald-50 hover:text-emerald-800">Reorder</button></td></tr>)}</tbody></table>{!lowStock.length && <EmptyState message={items.some((item) => item.quantity <= item.minLevel) ? "No matching stock alerts" : "No items need attention"} detail={items.some((item) => item.quantity <= item.minLevel) ? "Try a different search." : "Your stock levels are looking healthy."} clear={items.some((item) => item.quantity <= item.minLevel) ? onClearSearch : undefined}/>}</div><div className="flex justify-between border-t border-[#e4e4e7] px-5 py-3 text-xs text-slate-500"><span>{lowStock.length} items need attention</span><button onClick={() => onNavigate("Stock")} className="text-emerald-700">Open stock report</button></div></section><section className="overflow-hidden rounded-xl border border-[#e4e4e7] bg-white"><div className="flex items-center justify-between border-b border-[#e4e4e7] px-5 py-4"><div><h3 className="text-base font-semibold">Recent activity</h3><p className="mt-1 text-sm text-slate-500">Latest stock movements</p></div><button onClick={() => onNavigate("Stock")} aria-label="View activity" className="rounded-lg p-2 text-slate-500 hover:bg-slate-100"><ChevronRight size={17}/></button></div><div className="divide-y divide-[#e4e4e7]">{movements.slice(0, 6).map((movement) => { const plus = movement.delta > 0; return <button key={movement.id} onClick={() => onSelect(movement.itemId)} className="flex w-full items-start gap-3 px-5 py-4 text-left hover:bg-slate-50/70"><span className={`mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-full ${plus ? "bg-emerald-50 text-emerald-700" : "bg-rose-50 text-rose-700"}`}>{plus ? <ArrowDownLeft size={16}/> : <ArrowUpRight size={16}/>}</span><span className="min-w-0 flex-1"><span className="flex items-center justify-between gap-3"><span className="truncate text-sm font-medium">{movement.itemName}</span><span className={`shrink-0 text-sm font-semibold tabular-nums ${plus ? "text-emerald-700" : "text-rose-700"}`}>{plus ? "+" : ""}{movement.delta} units</span></span><span className="mt-1 block truncate text-xs text-slate-500">{movement.referenceId} · {movement.note}</span><span className="mt-1.5 block text-[11px] text-slate-400">{timeLabel(movement.timestamp)}</span></span></button> })}</div><button onClick={() => onNavigate("Stock")} className="w-full border-t border-[#e4e4e7] px-5 py-3 text-left text-sm font-medium text-emerald-700">View stock ledger <ChevronRight size={15} className="ml-1 inline"/></button></section></div><div className="mt-6 flex items-center gap-2 text-xs text-slate-500"><CircleHelp size={14}/>Inventory is synced across Mumbai Central, Pune Depot, and Chennai Hub.</div></>
}

function StockLevel({ item }: { item: InventoryItem }) { const percent = item.minLevel ? Math.min(100, Math.round(item.quantity / item.minLevel * 100)) : 100; return <div className="flex min-w-[130px] items-center gap-2"><span className="w-[68px] whitespace-nowrap text-xs font-medium tabular-nums text-slate-700">{item.quantity} / {item.minLevel}</span><div className="h-1.5 w-12 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${itemStatus(item) === "In stock" ? "bg-emerald-600" : itemStatus(item) === "Out of stock" ? "bg-rose-600" : "bg-amber-500"}`} style={{ width: `${percent}%` }}/></div></div> }
function StatusBadge({ status }: { status: string }) { return <span className={`inline-flex items-center gap-1.5 whitespace-nowrap rounded-full px-2.5 py-1 text-xs font-medium ${statusClass(status)}`}><span className={`size-1.5 rounded-full ${status === "Paid" || status === "Received" || status === "In stock" ? "bg-emerald-600" : status === "Out of stock" ? "bg-rose-600" : "bg-amber-600"}`}/>{status}</span> }
function EmptyState({ message, detail, clear }: { message: string; detail?: string; clear?: () => void }) { return <div className="flex flex-col items-center justify-center px-6 py-12 text-center"><span className="flex size-10 items-center justify-center rounded-full bg-slate-100 text-slate-500"><PackageSearch size={18}/></span><p className="mt-3 text-sm font-semibold text-slate-800">{message}</p>{detail && <p className="mt-1 text-sm text-slate-500">{detail}</p>}{clear && <button onClick={clear} className="mt-3 text-sm font-medium text-emerald-700">Clear filters</button>}</div> }
function FilterBar({ search, onSearch, children, summary, onClear, placeholder }: { search: string; onSearch: (value: string) => void; children?: ReactNode; summary?: string; onClear?: () => void; placeholder: string }) { return <div className="mb-5 rounded-xl border border-[#e4e4e7] bg-white p-4"><div className="flex flex-wrap items-center gap-3"><label className="relative min-w-[220px] flex-1"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={search} onChange={(event) => onSearch(event.target.value)} placeholder={placeholder} aria-label={placeholder} className="h-9 w-full rounded-lg border border-[#e4e4e7] pl-9 pr-3 text-sm outline-none focus:border-slate-900 focus:ring-2 focus:ring-slate-900/10"/></label>{children}</div>{summary && <div className="mt-3 flex items-center justify-between border-t border-slate-100 pt-3 text-xs text-slate-500"><span>{summary}</span><button onClick={onClear} className="font-medium text-emerald-700">Clear filters</button></div>}</div> }
function Pills<T extends string>({ options, value, onChange }: { options: T[]; value: T; onChange: (value: T) => void }) { return <div className="flex flex-wrap gap-1.5" role="group">{options.map((option) => <button key={option} onClick={() => onChange(option)} aria-pressed={option === value} className={`h-9 rounded-lg px-3 text-sm font-medium transition-colors ${option === value ? "bg-emerald-50 text-emerald-800" : "text-slate-600 hover:bg-slate-50"}`}>{option}</button>)}</div> }

function StockView({ items, movements, search, onSearch, onSelect }: { items: InventoryItem[]; movements: ReturnType<typeof useInventory>["movements"]; search: string; onSearch: (value: string) => void; onSelect: (id: string) => void }) {
  const [status, setStatus] = useState<Status>("All"); const [godown, setGodown] = useState("All godowns")
  const filtered = items.filter((item) => `${item.sku} ${item.name}`.toLowerCase().includes(search.toLowerCase()) && (status === "All" || itemStatus(item) === status) && (godown === "All godowns" || item.godown === godown))
  const active = search.length > 0 || status !== "All" || godown !== "All godowns"
  return <><PageIntro title="Stock" description="Track inventory levels and review every stock movement."/><FilterBar search={search} onSearch={onSearch} placeholder="Search by SKU or item name" summary={active ? `${filtered.length} of ${items.length} items · ${status !== "All" ? status : "All statuses"} · ${godown}` : undefined} onClear={() => { onSearch(""); setStatus("All"); setGodown("All godowns") }}><Pills options={["All", "In stock", "Low stock", "Out of stock"] as Status[]} value={status} onChange={setStatus}/><select value={godown} onChange={(event) => setGodown(event.target.value)} aria-label="Filter by godown" className="h-9 rounded-lg border border-[#e4e4e7] bg-white px-3 text-sm text-slate-700 outline-none focus:border-emerald-600"><option>All godowns</option>{godowns.map((entry) => <option key={entry}>{entry}</option>)}</select></FilterBar><div className="overflow-hidden rounded-xl border border-[#e4e4e7] bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[950px] text-left"><thead className="bg-slate-50/80"><tr className="text-xs font-medium text-slate-500"><th className="px-5 py-3">SKU</th><th className="px-4 py-3">Item name &amp; category</th><th className="px-4 py-3">Godown</th><th className="px-4 py-3">Stock level</th><th className="px-4 py-3 text-right">Unit price</th><th className="px-4 py-3">Status</th><th className="px-5 py-3 text-right">History</th></tr></thead><tbody className="divide-y divide-[#e4e4e7]">{filtered.map((item) => <tr key={item.id} onClick={() => onSelect(item.id)} className="cursor-pointer transition-colors hover:bg-slate-50/70"><td className="whitespace-nowrap px-5 py-4 font-mono text-xs font-medium text-slate-600">{item.sku}</td><td className="px-4 py-4"><p className="text-sm font-medium">{item.name}</p><p className="mt-1 text-xs text-slate-500">{item.category}</p></td><td className="px-4 py-4"><span className="rounded-md bg-slate-100 px-2.5 py-1 text-xs font-medium text-slate-700">{item.godown}</span></td><td className="px-4 py-4"><StockLevel item={item}/></td><td className="px-4 py-4 text-right text-sm font-medium tabular-nums">{formatINR(item.unitPrice)}<span className="text-xs font-normal text-slate-500"> / {item.unit}</span></td><td className="px-4 py-4"><StatusBadge status={itemStatus(item)}/></td><td className="px-5 py-4 text-right"><button onClick={(event) => { event.stopPropagation(); onSelect(item.id) }} className="rounded-md px-2 py-1.5 text-xs font-medium text-emerald-700 hover:bg-emerald-50">View history</button></td></tr>)}</tbody></table>{!filtered.length && <EmptyState message="No stock items found" detail="Try changing your search or filters." clear={active ? () => { onSearch(""); setStatus("All"); setGodown("All godowns") } : undefined}/>}</div><div className="border-t border-[#e4e4e7] px-5 py-3 text-xs text-slate-500">Showing {filtered.length} of {items.length} items · {movements.length} ledger entries</div></div></>
}

function PurchaseView({ purchases, onSelect, onCreate, onReceive }: { purchases: PurchaseOrder[]; onSelect: (id: string) => void; onCreate: () => void; onReceive: (id: string) => void }) {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState("All")
  const filtered = purchases.filter((po) => `${po.id} ${po.supplier}`.toLowerCase().includes(search.toLowerCase()) && (status === "All" || po.status === status))
  const active = search.length > 0 || status !== "All"
  return <><PageIntro title="Purchase orders" description="Manage supplier orders and keep replenishment moving." action={<button className={primaryClass} onClick={onCreate}><Plus size={16}/>New purchase</button>}/><FilterBar search={search} onSearch={setSearch} placeholder="Search by PO# or supplier name" summary={active ? `${filtered.length} of ${purchases.length} purchase orders · ${status}` : undefined} onClear={() => { setSearch(""); setStatus("All") }}><Pills options={["All", "Pending", "Received"]} value={status} onChange={setStatus}/></FilterBar><div className="overflow-hidden rounded-xl border border-[#e4e4e7] bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[930px] text-left"><thead className="bg-slate-50/80"><tr className="text-xs font-medium text-slate-500"><th className="px-5 py-3">PO#</th><th className="px-4 py-3">Supplier</th><th className="px-4 py-3">Items</th><th className="px-4 py-3">Expected date</th><th className="px-4 py-3 text-right">Total amount</th><th className="px-4 py-3">Status</th><th className="px-5 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-[#e4e4e7]">{filtered.map((po) => <tr key={po.id} onClick={() => onSelect(po.id)} className="cursor-pointer hover:bg-slate-50/70"><td className="px-5 py-4 font-mono text-xs font-semibold text-slate-700">{po.id}</td><td className="px-4 py-4 text-sm font-medium">{po.supplier}</td><td className="px-4 py-4"><p className="text-sm">{po.items.length} {po.items.length === 1 ? "item" : "items"}</p><p className="mt-1 max-w-[190px] truncate text-xs text-slate-500">{po.items[0]?.itemName ?? "—"}{po.items.length > 1 ? ` + ${po.items.length - 1} more` : ""}</p></td><td className="px-4 py-4 text-sm text-slate-600">{dateLabel(po.expectedDate)}</td><td className="px-4 py-4 text-right text-sm font-semibold tabular-nums">{formatINR(po.totalAmount)}</td><td className="px-4 py-4"><StatusBadge status={po.status}/></td><td className="px-5 py-4 text-right">{po.status === "Pending" ? <button onClick={(event) => { event.stopPropagation(); onReceive(po.id) }} className="h-8 rounded-md border border-emerald-200 bg-emerald-50 px-3 text-xs font-semibold text-emerald-800 hover:bg-emerald-100">Mark received</button> : <button onClick={(event) => { event.stopPropagation(); onSelect(po.id) }} className="rounded-md px-2 py-1.5 text-xs font-medium text-slate-600 hover:bg-slate-100">View order</button>}</td></tr>)}</tbody></table>{!filtered.length && <EmptyState message="No purchase orders found" detail="Try changing your search or filters." clear={active ? () => { setSearch(""); setStatus("All") } : undefined}/>}</div><div className="border-t border-[#e4e4e7] px-5 py-3 text-xs text-slate-500">Showing {filtered.length} purchase orders</div></div></>
}

function SalesView({ sales, onSelect, onCreate, onPaid }: { sales: SaleOrder[]; onSelect: (id: string) => void; onCreate: () => void; onPaid: (id: string) => void }) {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState("All")
  const filtered = sales.filter((sale) => `${sale.id} ${sale.customer}`.toLowerCase().includes(search.toLowerCase()) && (status === "All" || sale.status === status)); const active = !!search || status !== "All"
  return <><PageIntro title="Sales orders" description="Review customer orders, invoices, and payment status." action={<button className={primaryClass} onClick={onCreate}><Plus size={16}/>New sale</button>}/><FilterBar search={search} onSearch={setSearch} placeholder="Search by SO# or customer name" summary={active ? `${filtered.length} of ${sales.length} sales orders · ${status}` : undefined} onClear={() => { setSearch(""); setStatus("All") }}><Pills options={["All", "Draft", "Confirmed", "Paid"]} value={status} onChange={setStatus}/></FilterBar><div className="overflow-hidden rounded-xl border border-[#e4e4e7] bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[930px] text-left"><thead className="bg-slate-50/80"><tr className="text-xs font-medium text-slate-500"><th className="px-5 py-3">Invoice / SO#</th><th className="px-4 py-3">Customer</th><th className="px-4 py-3">Items</th><th className="px-4 py-3">Date</th><th className="px-4 py-3 text-right">Total amount</th><th className="px-4 py-3">Status</th><th className="px-5 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-[#e4e4e7]">{filtered.map((sale) => <tr key={sale.id} onClick={() => onSelect(sale.id)} className="cursor-pointer hover:bg-slate-50/70"><td className="px-5 py-4 font-mono text-xs font-semibold text-slate-700">{sale.id}</td><td className="px-4 py-4 text-sm font-medium">{sale.customer}</td><td className="px-4 py-4"><p className="text-sm">{sale.items.length} {sale.items.length === 1 ? "item" : "items"}</p><p className="mt-1 max-w-[190px] truncate text-xs text-slate-500">{sale.items[0]?.itemName ?? "—"}{sale.items.length > 1 ? ` + ${sale.items.length - 1} more` : ""}</p></td><td className="px-4 py-4 text-sm text-slate-600">{dateLabel(sale.date)}</td><td className="px-4 py-4 text-right text-sm font-semibold tabular-nums">{formatINR(sale.totalAmount)}</td><td className="px-4 py-4"><StatusBadge status={sale.status}/></td><td className="px-5 py-4 text-right">{sale.status === "Confirmed" ? <button onClick={(event) => { event.stopPropagation(); onPaid(sale.id) }} className="h-8 rounded-md border border-[#e4e4e7] bg-white px-3 text-xs font-semibold text-slate-700 hover:bg-slate-50">Mark paid</button> : <button onClick={(event) => { event.stopPropagation(); onSelect(sale.id) }} className="rounded-md px-2 py-1.5 text-xs font-medium text-emerald-700 hover:bg-emerald-50">View invoice</button>}</td></tr>)}</tbody></table>{!filtered.length && <EmptyState message="No sales orders found" detail="Try changing your search or filters." clear={active ? () => { setSearch(""); setStatus("All") } : undefined}/>}</div><div className="border-t border-[#e4e4e7] px-5 py-3 text-xs text-slate-500">Showing {filtered.length} sales orders</div></div></>
}
function PageIntro({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><h2 className="text-[26px] font-semibold tracking-[-0.04em]">{title}</h2><p className="mt-1 text-sm text-slate-600">{description}</p></div>{action}</div> }

function ReportsView({ items, sales, purchases }: { items: InventoryItem[]; sales: SaleOrder[]; purchases: PurchaseOrder[] }) {
  const [tab, setTab] = useState("Stock report"); const [godown, setGodown] = useState("All godowns"); const [status, setStatus] = useState("All")
  const currentItems = items.filter((item) => godown === "All godowns" || item.godown === godown)
  const currentSales = sales.filter((sale) => status === "All" || sale.status === status)
  const currentPurchases = purchases.filter((po) => status === "All" || po.status === status)
  const stockChart = Object.entries(currentItems.reduce<Record<string, number>>((acc, item) => { acc[item.category] = (acc[item.category] ?? 0) + item.quantity * item.unitPrice; return acc }, {})).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value)
  const salesChart = Object.entries(currentSales.reduce<Record<string, number>>((acc, sale) => { acc[sale.customer.split(",")[0]] = (acc[sale.customer.split(",")[0]] ?? 0) + sale.totalAmount * 1.18; return acc }, {})).map(([name, revenue]) => ({ name, revenue })).sort((a, b) => b.revenue - a.revenue)
  const purchaseChart = Object.entries(currentPurchases.reduce<Record<string, { pending: number; received: number }>>((acc, po) => { acc[po.supplier] ??= { pending: 0, received: 0 }; acc[po.supplier][po.status === "Pending" ? "pending" : "received"] += po.totalAmount; return acc }, {})).map(([name, value]) => ({ name: name.split(" ").slice(0, 2).join(" "), ...value }))
  const rows = tab === "Stock report" ? currentItems.map((item) => [item.sku, item.name, item.category, item.godown, item.quantity, item.minLevel, item.quantity * item.unitPrice, itemStatus(item)]) : tab === "Sales report" ? currentSales.map((sale) => [sale.id, sale.customer, sale.date, sale.items.reduce((sum, line) => sum + line.quantity, 0), sale.totalAmount, sale.totalAmount * 0.18, sale.totalAmount * 1.18, sale.status]) : currentPurchases.map((po) => [po.id, po.supplier, po.expectedDate, po.items.reduce((sum, line) => sum + line.quantity, 0), po.totalAmount, po.status])
  const exportCsv = () => { const headers = tab === "Stock report" ? ["SKU", "Item", "Category", "Godown", "Quantity", "Minimum level", "Stock value INR", "Status"] : tab === "Sales report" ? ["SO", "Customer", "Date", "Units", "Subtotal INR", "GST INR", "Grand total INR", "Status"] : ["PO", "Supplier", "Expected date", "Units", "Total INR", "Status"]; const csv = [headers, ...rows].map((row) => row.map((value) => `"${String(value).replaceAll('"', '""')}"`).join(",")).join("\r\n"); const blob = new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${tab.toLowerCase().replaceAll(" ", "-")}.csv`; anchor.click(); URL.revokeObjectURL(url); toast.success(`${tab} exported to CSV`) }
  const setTabClean = (value: string) => { setTab(value); setStatus("All"); setGodown("All godowns") }
  return <><PageIntro title="Reports" description="Live summaries of your stock, sales, and purchasing."/><div className="mb-5 flex flex-wrap items-center justify-between gap-4 border-b border-[#e4e4e7]"><div className="flex gap-1">{["Stock report", "Sales report", "Purchase report"].map((value) => <button key={value} onClick={() => setTabClean(value)} className={`border-b-2 px-4 py-3 text-sm font-medium ${tab === value ? "border-emerald-600 text-emerald-800" : "border-transparent text-slate-500 hover:text-slate-800"}`}>{value}</button>)}</div><button className={buttonClass} onClick={exportCsv}><Download size={15}/>Export CSV</button></div><div className="mb-5 flex flex-wrap gap-2">{tab === "Stock report" ? <select value={godown} onChange={(event) => setGodown(event.target.value)} className="h-9 rounded-lg border border-[#e4e4e7] bg-white px-3 text-sm"><option>All godowns</option>{godowns.map((entry) => <option key={entry}>{entry}</option>)}</select> : <Pills options={tab === "Sales report" ? ["All", "Draft", "Confirmed", "Paid"] : ["All", "Pending", "Received"]} value={status} onChange={setStatus}/>}</div>
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">{(tab === "Stock report" ? [{ title: "Stock value", value: formatINR(currentItems.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0)), note: `${currentItems.length} SKUs` }, { title: "Units on hand", value: currentItems.reduce((sum, item) => sum + item.quantity, 0).toLocaleString("en-IN"), note: "Across selected godown" }, { title: "Low stock items", value: currentItems.filter((item) => item.quantity <= item.minLevel).length, note: "At or below minimum" }] : tab === "Sales report" ? [{ title: "Order revenue", value: formatINR(currentSales.reduce((sum, sale) => sum + sale.totalAmount, 0)), note: `${currentSales.length} orders` }, { title: "GST at 18%", value: formatINR(currentSales.reduce((sum, sale) => sum + sale.totalAmount * 0.18, 0)), note: "Estimated tax" }, { title: "Invoice total", value: formatINR(currentSales.reduce((sum, sale) => sum + sale.totalAmount * 1.18, 0)), note: "Including GST" }] : [{ title: "Purchase spend", value: formatINR(currentPurchases.reduce((sum, po) => sum + po.totalAmount, 0)), note: `${currentPurchases.length} orders` }, { title: "Pending spend", value: formatINR(currentPurchases.filter((po) => po.status === "Pending").reduce((sum, po) => sum + po.totalAmount, 0)), note: "Awaiting delivery" }, { title: "Received orders", value: currentPurchases.filter((po) => po.status === "Received").length, note: "Delivered to godown" }]).map((metric) => <article key={metric.title} className="rounded-xl border border-[#e4e4e7] bg-white p-5"><p className="text-sm font-medium text-slate-600">{metric.title}</p><p className="mt-3 text-2xl font-semibold tracking-tight tabular-nums">{metric.value}</p><p className="mt-1 text-xs text-slate-500">{metric.note}</p></article>)}</div>
    <section className="mt-5 rounded-xl border border-[#e4e4e7] bg-white p-5"><div className="mb-5"><h3 className="font-semibold">{tab === "Stock report" ? "Stock value by category" : tab === "Sales report" ? "Sales revenue by customer (incl. GST)" : "Purchase spend by supplier and status"}</h3><p className="mt-1 text-sm text-slate-500">{tab === "Sales report" ? "Order subtotals with 18% GST applied" : "Values update automatically with your inventory activity"}</p></div><div className="h-[300px] w-full">{tab === "Stock report" ? <ResponsiveContainer width="100%" height="100%"><BarChart data={stockChart} layout="vertical" margin={{ left: 20, right: 30, top: 8, bottom: 8 }}><CartesianGrid stroke="#e4e4e7" horizontal={false}/><XAxis type="number" tickFormatter={(value) => `₹${Number(value).toLocaleString("en-IN")}`} tick={{ fill: "#64748b", fontSize: 11 }} axisLine={false} tickLine={false}/><YAxis type="category" dataKey="name" width={145} tick={{ fill: "#475569", fontSize: 11 }} axisLine={false} tickLine={false}/><Tooltip formatter={(value) => formatINR(Number(value))} contentStyle={{ borderRadius: 10, borderColor: "#e4e4e7", fontSize: 12 }}/><Bar dataKey="value" fill="#059669" radius={[0, 5, 5, 0]} barSize={18}/></BarChart></ResponsiveContainer> : tab === "Sales report" ? <ResponsiveContainer width="100%" height="100%"><AreaChart data={salesChart} margin={{ left: 8, right: 15, top: 10, bottom: 30 }}><defs><linearGradient id="salesGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#059669" stopOpacity={0.2}/><stop offset="95%" stopColor="#059669" stopOpacity={0.02}/></linearGradient></defs><CartesianGrid stroke="#e4e4e7" vertical={false}/><XAxis dataKey="name" tick={{ fill: "#64748b", fontSize: 11 }} axisLine={false} tickLine={false} angle={-12} textAnchor="end"/><YAxis tickFormatter={(value) => `₹${Number(value / 1000).toFixed(0)}k`} tick={{ fill: "#64748b", fontSize: 11 }} axisLine={false} tickLine={false}/><Tooltip formatter={(value) => formatINR(Number(value))} contentStyle={{ borderRadius: 10, borderColor: "#e4e4e7", fontSize: 12 }}/><Area type="monotone" dataKey="revenue" stroke="#059669" strokeWidth={2} fill="url(#salesGradient)"/></AreaChart></ResponsiveContainer> : <ResponsiveContainer width="100%" height="100%"><BarChart data={purchaseChart} margin={{ left: 6, right: 15, top: 12, bottom: 24 }}><CartesianGrid stroke="#e4e4e7" vertical={false}/><XAxis dataKey="name" tick={{ fill: "#64748b", fontSize: 11 }} axisLine={false} tickLine={false}/><YAxis tickFormatter={(value) => `₹${Number(value / 1000).toFixed(0)}k`} tick={{ fill: "#64748b", fontSize: 11 }} axisLine={false} tickLine={false}/><Tooltip formatter={(value) => formatINR(Number(value))} contentStyle={{ borderRadius: 10, borderColor: "#e4e4e7", fontSize: 12 }}/><Bar dataKey="pending" name="Pending" stackId="a" fill="#d97706" radius={[0, 0, 0, 0]}/><Bar dataKey="received" name="Received" stackId="a" fill="#059669" radius={[4, 4, 0, 0]}/></BarChart></ResponsiveContainer>}</div></section>
    <section className="mt-5 overflow-hidden rounded-xl border border-[#e4e4e7] bg-white"><div className="border-b border-[#e4e4e7] px-5 py-4"><h3 className="font-semibold">{tab} details</h3><p className="mt-1 text-sm text-slate-500">{rows.length} records in the current report</p></div><div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left"><thead className="bg-slate-50/80"><tr className="text-xs text-slate-500">{(tab === "Stock report" ? ["SKU", "Item", "Category", "Godown", "Quantity", "Min level", "Stock value", "Status"] : tab === "Sales report" ? ["SO#", "Customer", "Date", "Units", "Subtotal", "GST", "Grand total", "Status"] : ["PO#", "Supplier", "Expected date", "Units", "Total amount", "Status"]).map((heading) => <th key={heading} className={`px-4 py-3 font-medium ${["Quantity", "Min level", "Stock value", "Units", "Subtotal", "GST", "Grand total", "Total amount"].includes(heading) ? "text-right" : "text-left"}`}>{heading}</th>)}</tr></thead><tbody className="divide-y divide-[#e4e4e7]">{rows.map((row, index) => <tr key={String(row[0])} className="text-sm">{row.map((cell, cellIndex) => <td key={cellIndex} className={`px-4 py-3 ${typeof cell === "number" ? "text-right tabular-nums" : ""} ${cellIndex === 0 ? "font-mono text-xs text-slate-600" : "text-slate-700"}`}>{typeof cell === "number" && (tab === "Stock report" && cellIndex === 6 || tab === "Sales report" && [4, 5, 6].includes(cellIndex) || tab === "Purchase report" && cellIndex === 4) ? formatINR(cell) : String(cell)}</td>)}</tr>)}</tbody></table>{!rows.length && <EmptyState message="No report data" detail="Try changing the selected filters." clear={status !== "All" || godown !== "All godowns" ? () => { setStatus("All"); setGodown("All godowns") } : undefined}/>}</div></section></>
}

function OrderModal({ type, prefillItem, onClose, onSale, onPurchase }: { type: "sale" | "purchase"; prefillItem?: string; onClose: () => void; onSale: (customer: string, lines: LineInput[]) => boolean; onPurchase: (supplier: string, lines: LineInput[], received?: boolean) => boolean }) {
  const { items, sales, purchases } = useInventory(); const [party, setParty] = useState(""); const [lines, setLines] = useState<LineInput[]>([{ itemId: prefillItem ?? "", quantity: prefillItem ? Math.max(1, (items.find((item) => item.id === prefillItem)?.minLevel ?? 1) * 2 - (items.find((item) => item.id === prefillItem)?.quantity ?? 0)) : 1 }]); const [showError, setShowError] = useState(false); const [saving, setSaving] = useState(false)
  const selectLine = (index: number, itemId: string) => setLines((current) => current.map((line, i) => i === index ? { ...line, itemId, unitPrice: undefined } : line))
  const updateLine = (index: number, patch: Partial<LineInput>) => setLines((current) => current.map((line, i) => i === index ? { ...line, ...patch } : line))
  const valid = party.trim().length > 0 && lines.length > 0 && lines.every((line) => !!line.itemId && Number.isInteger(line.quantity) && line.quantity > 0 && (type === "purchase" || line.quantity <= (items.find((item) => item.id === line.itemId)?.quantity ?? 0)))
  const total = lines.reduce((sum, entry) => sum + entry.quantity * (entry.unitPrice ?? items.find((item) => item.id === entry.itemId)?.unitPrice ?? 0), 0)
  const submit = (received = false) => { setShowError(true); if (!valid) return; setSaving(true); const success = type === "sale" ? onSale(party, lines) : onPurchase(party, lines, received); setSaving(false); if (success) onClose() }
  return <Overlay onClose={onClose} title={type === "sale" ? "Create a sale" : "New purchase order"} subtitle={type === "sale" ? "Create an order and update inventory" : "Add supplier items and set quantities"} width="max-w-[720px]"><div className="flex-1 space-y-5 overflow-y-auto p-6"><label className="block text-sm font-medium text-slate-700">{type === "sale" ? "Customer" : "Supplier"}<input list={type === "sale" ? "customer-options" : "supplier-options"} value={party} onChange={(event) => setParty(event.target.value)} placeholder={type === "sale" ? "Select or enter customer" : "Select or enter supplier"} className="mt-2 h-10 w-full rounded-lg border border-[#e4e4e7] px-3 text-sm outline-none focus:border-slate-900 focus:ring-2 focus:ring-slate-900/10"/><datalist id={type === "sale" ? "customer-options" : "supplier-options"}>{(type === "sale" ? sales.map((sale) => sale.customer) : purchases.map((purchase) => purchase.supplier)).filter((value, index, values) => values.indexOf(value) === index).map((value) => <option key={value} value={value}/>)}</datalist>{showError && !party.trim() && <span className="mt-1 block text-xs text-rose-700">Enter a customer or supplier name.</span>}</label><div className="flex items-center justify-between"><div><h3 className="text-sm font-semibold">Line items</h3><p className="mt-1 text-xs text-slate-500">Select items from your live inventory</p></div><button onClick={() => setLines((current) => [...current, { itemId: "", quantity: 1 }])} className="text-sm font-medium text-emerald-700"><Plus size={15} className="mr-1 inline"/>Add item</button></div>{lines.map((entry, index) => { const item = items.find((candidate) => candidate.id === entry.itemId); const exceeds = type === "sale" && item && entry.quantity > item.quantity; return <div key={index} className="rounded-xl border border-[#e4e4e7] p-4"><div className="grid grid-cols-1 gap-3 sm:grid-cols-[1fr_110px_140px_auto]"><label className="text-xs font-medium text-slate-600">Item<select value={entry.itemId} onChange={(event) => selectLine(index, event.target.value)} className="mt-1.5 h-9 w-full rounded-lg border border-[#e4e4e7] bg-white px-2 text-sm"><option value="">Select an item</option>{items.map((candidate) => <option key={candidate.id} value={candidate.id} disabled={lines.some((line, lineIndex) => lineIndex !== index && line.itemId === candidate.id)}>{candidate.sku} · {candidate.name}</option>)}</select></label><label className="text-xs font-medium text-slate-600">Quantity<input type="number" min="1" value={entry.quantity} onChange={(event) => updateLine(index, { quantity: Number(event.target.value) })} className={`mt-1.5 h-9 w-full rounded-lg border px-2 text-sm tabular-nums ${exceeds ? "border-rose-500 bg-rose-50" : "border-[#e4e4e7]"}`}/></label><label className="text-xs font-medium text-slate-600">Unit cost<input type="number" min="0.01" step="0.01" value={entry.unitPrice ?? item?.unitPrice ?? ""} disabled={type === "sale"} onChange={(event) => updateLine(index, { unitPrice: Number(event.target.value) })} className="mt-1.5 h-9 w-full rounded-lg border border-[#e4e4e7] px-2 text-sm tabular-nums disabled:bg-slate-50"/></label><button disabled={lines.length === 1} onClick={() => setLines((current) => current.filter((_, i) => i !== index))} className="mt-5 rounded-md p-2 text-slate-400 hover:bg-slate-100 disabled:opacity-30" aria-label="Remove line item"><X size={16}/></button></div>{item && <p className={`mt-2 text-xs ${exceeds ? "text-rose-700" : "text-slate-500"}`}>{type === "sale" ? `Available: ${item.quantity} units in ${item.godown}` : `Current stock: ${item.quantity} units in ${item.godown}`}{exceeds ? ` · Only ${item.quantity} units available in ${item.godown}` : ""}</p>}{showError && !item && <p className="mt-2 text-xs text-rose-700">Choose an inventory item.</p>}</div> })}<div className="flex items-center justify-between border-t border-[#e4e4e7] pt-4"><span className="text-sm font-medium text-slate-600">Order total</span><span className="text-xl font-semibold tabular-nums">{formatINR(total)}</span></div></div><div className="flex flex-wrap justify-end gap-2 border-t border-[#e4e4e7] p-5"><button className={buttonClass} onClick={onClose}>Cancel</button>{type === "purchase" && <button className={buttonClass} disabled={!valid || saving} onClick={() => submit(true)}><Check size={15}/>Create &amp; mark received</button>}<button className={primaryClass} disabled={!valid || saving} onClick={() => submit(false)}>{type === "sale" ? "Confirm sale" : "Create purchase order"}</button></div></Overlay>
}

function DetailDrawer({ drawer, onClose, onReceive, onAdjust, onPaid }: { drawer: NonNullable<React.ComponentProps<typeof DrawerContent> ["drawer"]>; onClose: () => void; onReceive: (id: string) => void; onAdjust: (id: string, delta: number, note: string) => boolean; onPaid: (id: string) => void }) { return <DrawerContent drawer={drawer} onClose={onClose} onReceive={onReceive} onAdjust={onAdjust} onPaid={onPaid}/> }
function DrawerContent({ drawer, onClose, onReceive, onAdjust, onPaid }: { drawer: { type: "stock"; id: string } | { type: "purchase"; id: string } | { type: "sale"; id: string }; onClose: () => void; onReceive: (id: string) => void; onAdjust: (id: string, delta: number, note: string) => boolean; onPaid: (id: string) => void }) {
  const { items, movements, purchases, sales } = useInventory(); const item = drawer.type === "stock" ? items.find((entry) => entry.id === drawer.id) : undefined; const po = drawer.type === "purchase" ? purchases.find((entry) => entry.id === drawer.id) : undefined; const sale = drawer.type === "sale" ? sales.find((entry) => entry.id === drawer.id) : undefined
  const [direction, setDirection] = useState<"Add" | "Remove">("Add"); const [qty, setQty] = useState(1); const [note, setNote] = useState("")
  return <div className="fixed inset-0 z-50 flex justify-end bg-slate-900/20" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose() }}><aside role="dialog" aria-modal="true" aria-label={item ? "Stock item details" : po ? "Purchase order details" : "Invoice preview"} className={`flex h-full w-full max-w-[520px] flex-col border-l border-[#e4e4e7] bg-white shadow-xl ${sale ? "print:static print:max-w-none print:shadow-none" : ""}`}>
    <div className="flex items-start justify-between border-b border-[#e4e4e7] px-6 py-5"><div>{item ? <><p className="font-mono text-xs text-slate-500">{item.sku}</p><h2 className="mt-1 text-lg font-semibold">{item.name}</h2><p className="mt-1 text-sm text-slate-500">{item.godown}</p></> : po ? <><p className="font-mono text-xs text-slate-500">{po.id}</p><h2 className="mt-1 text-lg font-semibold">Purchase order</h2><p className="mt-1 text-sm text-slate-500">{po.supplier}</p></> : sale ? <><p className="text-xs font-medium text-emerald-700">Gada Electronics · Tax invoice</p><h2 className="mt-1 text-lg font-semibold">Invoice {sale.id}</h2><p className="mt-1 text-sm text-slate-500">{sale.customer} · {dateLabel(sale.date)}</p></> : null}</div><button onClick={onClose} aria-label="Close details" className="rounded-lg p-2 text-slate-500 hover:bg-slate-100 print:hidden"><X size={18}/></button></div>
    <div className="flex-1 overflow-y-auto p-6">{item && <><div className="grid grid-cols-2 gap-3"><Metric label="Current stock" value={`${item.quantity} ${item.unit}`}/><Metric label="Minimum level" value={`${item.minLevel} ${item.unit}`}/><Metric label="Godown" value={item.godown}/><Metric label="Stock valuation" value={formatINR(item.quantity * item.unitPrice)}/></div><div className="mt-6 rounded-xl border border-[#e4e4e7] p-4"><h3 className="text-sm font-semibold">Quick stock adjustment</h3><div className="mt-3 grid grid-cols-[110px_1fr] gap-3"><label className="text-xs font-medium text-slate-600">Action<select value={direction} onChange={(event) => setDirection(event.target.value as "Add" | "Remove")} className="mt-1.5 h-9 w-full rounded-lg border border-[#e4e4e7] bg-white px-2 text-sm"><option>Add</option><option>Remove</option></select></label><label className="text-xs font-medium text-slate-600">Units<input type="number" min="1" value={qty} onChange={(event) => setQty(Number(event.target.value))} className="mt-1.5 h-9 w-full rounded-lg border border-[#e4e4e7] px-3 text-sm tabular-nums"/></label></div><label className="mt-3 block text-xs font-medium text-slate-600">Reason note<input value={note} onChange={(event) => setNote(event.target.value)} placeholder="e.g. Cycle count correction" className="mt-1.5 h-9 w-full rounded-lg border border-[#e4e4e7] px-3 text-sm"/></label><button className={`${primaryClass} mt-4 w-full`} onClick={() => { if (onAdjust(item.id, direction === "Add" ? qty : -qty, note)) { setQty(1); setNote("") } }}>Save adjustment</button></div><div className="mt-7"><h3 className="text-sm font-semibold">Stock movement history</h3><div className="mt-4">{movements.filter((entry) => entry.itemId === item.id).sort((a, b) => +new Date(b.timestamp) - +new Date(a.timestamp)).map((entry) => <div key={entry.id} className="relative flex gap-3 border-l border-slate-200 pb-5 pl-5 last:border-0"><span className={`absolute -left-[5px] top-1 size-2.5 rounded-full border-2 border-white ${entry.delta > 0 ? "bg-emerald-600" : "bg-rose-600"}`}/><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><span className="text-sm font-semibold">{entry.type === "PURCHASE" ? "Purchase received" : entry.type === "SALE" ? "Sale dispatched" : "Stock adjustment"}</span><span className={`text-sm font-semibold tabular-nums ${entry.delta > 0 ? "text-emerald-700" : "text-rose-700"}`}>{entry.delta > 0 ? "+" : ""}{entry.delta}</span></div><p className="mt-1 text-xs text-slate-500">{entry.referenceId} · Balance {entry.resultingQty} units</p><p className="mt-1 text-xs text-slate-500">{entry.note}</p><p className="mt-1 text-[11px] text-slate-400">{timeLabel(entry.timestamp)}</p></div></div>)}{!movements.some((entry) => entry.itemId === item.id) && <p className="text-sm text-slate-500">No stock movements recorded yet.</p>}</div></div></>}{po && <><div className="grid grid-cols-2 gap-3"><Metric label="Supplier" value={po.supplier}/><Metric label="Expected date" value={dateLabel(po.expectedDate)}/><Metric label="Total amount" value={formatINR(po.totalAmount)}/><Metric label="Status" value={po.status}/></div><h3 className="mb-3 mt-7 text-sm font-semibold">Line items</h3>{po.items.map((line) => <div key={line.itemId} className="flex items-center justify-between border-b border-slate-100 py-3"><div><p className="text-sm font-medium">{line.itemName}</p><p className="mt-1 text-xs text-slate-500">{line.sku} · {line.quantity} units</p></div><span className="text-sm font-medium tabular-nums">{formatINR(line.quantity * line.unitPrice)}</span></div>)}{po.status === "Pending" && <button className={`${primaryClass} mt-6 w-full`} onClick={(event) => { event.stopPropagation(); onReceive(po.id) }}>Mark received</button>}</>}{sale && <div className="invoice-content"><div className="flex items-start justify-between border-b border-slate-200 pb-5"><div><p className="text-xl font-semibold">SasthaStock</p><p className="mt-1 text-xs text-slate-500">Electrical &amp; industrial supplies</p><p className="mt-1 text-xs text-slate-500">Mumbai, Maharashtra · GSTIN 27AABCS1234F1Z5</p></div><StatusBadge status={sale.status}/></div><div className="grid grid-cols-2 gap-4 py-5 text-sm"><div><p className="text-xs text-slate-500">Bill to</p><p className="mt-1 font-semibold">{sale.customer}</p><p className="mt-1 text-xs text-slate-500">Business customer · India</p></div><div className="text-right"><p className="text-xs text-slate-500">Invoice number</p><p className="mt-1 font-mono font-semibold">{sale.id}</p><p className="mt-1 text-xs text-slate-500">Invoice date · {dateLabel(sale.date)}</p></div></div><table className="w-full text-left text-xs"><thead><tr className="border-y border-slate-200 text-slate-500"><th className="py-3 font-medium">Item description</th><th className="py-3 text-right font-medium">Qty</th><th className="py-3 text-right font-medium">Rate</th><th className="py-3 text-right font-medium">Amount</th></tr></thead><tbody>{sale.items.map((entry) => <tr key={entry.itemId} className="border-b border-slate-100"><td className="py-3 pr-2"><p className="font-medium text-slate-800">{entry.itemName}</p><p className="mt-1 text-slate-500">{entry.sku}</p></td><td className="py-3 text-right tabular-nums">{entry.quantity}</td><td className="py-3 text-right tabular-nums">{formatINR(entry.unitPrice)}</td><td className="py-3 text-right font-medium tabular-nums">{formatINR(entry.quantity * entry.unitPrice)}</td></tr>)}</tbody></table><div className="ml-auto mt-5 max-w-[230px] space-y-3 text-sm"><div className="flex justify-between text-slate-600"><span>Subtotal</span><span className="tabular-nums">{formatINR(sale.totalAmount)}</span></div><div className="flex justify-between text-slate-600"><span>GST (18%)</span><span className="tabular-nums">{formatINR(sale.totalAmount * .18)}</span></div><div className="flex justify-between border-t border-slate-200 pt-3 font-semibold"><span>Grand total</span><span className="tabular-nums">{formatINR(sale.totalAmount * 1.18)}</span></div></div><p className="mt-8 border-t border-slate-200 pt-4 text-xs text-slate-500">Thank you for your business. Please retain this invoice for your records.</p></div>}</div>
    {(item || sale) && <div className="flex gap-2 border-t border-[#e4e4e7] p-5 print:hidden">{sale && <button className={buttonClass} onClick={() => window.print()}><Printer size={15}/>Print / Save PDF</button>}{sale?.status === "Confirmed" && <button className={`${primaryClass} flex-1`} onClick={(event) => { event.stopPropagation(); onPaid(sale.id) }}>Mark as paid</button>}</div>}
  </aside></div>
}
function Metric({ label, value }: { label: string; value: string }) { return <div className="rounded-lg border border-[#e4e4e7] p-3"><p className="text-xs text-slate-500">{label}</p><p className="mt-1.5 text-sm font-semibold tabular-nums">{value}</p></div> }
function Overlay({ onClose, title, subtitle, children, width }: { onClose: () => void; title: string; subtitle: string; children: ReactNode; width: string }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/30 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose() }}><section role="dialog" aria-modal="true" aria-labelledby="modal-title" className={`flex max-h-[92vh] w-full ${width} flex-col overflow-hidden rounded-2xl border border-[#e4e4e7] bg-white shadow-xl`}><div className="flex items-start justify-between border-b border-[#e4e4e7] px-6 py-5"><div><h2 id="modal-title" className="text-lg font-semibold">{title}</h2><p className="mt-1 text-sm text-slate-500">{subtitle}</p></div><button onClick={onClose} aria-label="Close dialog" className="rounded-lg p-2 text-slate-500 hover:bg-slate-100"><X size={18}/></button></div>{children}</section></div> }

export function InventoryApp() { return <InventoryProvider><AppContent/></InventoryProvider> }
